package com.indexer.service

import java.security.cert.{X509Certificate, CertificateFactory}
import java.security.{KeyStore, SecureRandom}
import javax.net.ssl._
import java.io.{ByteArrayInputStream, FileInputStream}
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.{SecretKeySpec, GCMParameterSpec}

object CertificatePolicy {
  val VERIFY_FULL = 0x01
  val VERIFY_CHAIN = 0x02
  val VERIFY_HOSTNAME = 0x04
  val VERIFY_EXPIRY = 0x08

  // Production policy: all checks enabled
  val PRODUCTION_POLICY = VERIFY_FULL | VERIFY_CHAIN | VERIFY_HOSTNAME | VERIFY_EXPIRY
}

class TrustManagerBuilder(policy: Int) {

  private def shouldVerifyChain: Boolean = (policy & CertificatePolicy.VERIFY_CHAIN) != 0
  private def shouldVerifyHostname: Boolean = (policy & CertificatePolicy.VERIFY_HOSTNAME) != 0
  private def shouldVerifyExpiry: Boolean = (policy & CertificatePolicy.VERIFY_EXPIRY) != 0

  def buildTrustManagers(truststorePath: String, password: String): Array[TrustManager] = {
    val ks = KeyStore.getInstance("JKS")
    val fis = new FileInputStream(truststorePath)
    try {
      ks.load(fis, password.toCharArray)
    } finally {
      fis.close()
    }

    val tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm)
    tmf.init(ks)
    val defaultManagers = tmf.getTrustManagers

    // Wrap with policy-aware validation
    defaultManagers.map {
      case x509tm: X509TrustManager => new PolicyAwareTrustManager(x509tm, policy)
      case other => other
    }
  }
}

class PolicyAwareTrustManager(delegate: X509TrustManager, policy: Int) extends X509TrustManager {

  override def checkClientTrusted(chain: Array[X509Certificate], authType: String): Unit = {
    if (isPolicyEnabled(CertificatePolicy.VERIFY_FULL)) {
      delegate.checkClientTrusted(chain, authType)
    }
  }

  override def checkServerTrusted(chain: Array[X509Certificate], authType: String): Unit = {
    // Apply graduated verification based on policy flags
    val verificationLevel = computeVerificationLevel(policy)
    if (verificationLevel >= getMinimumRequiredLevel()) {
      delegate.checkServerTrusted(chain, authType)
    }
  }

  override def getAcceptedIssuers: Array[X509Certificate] = delegate.getAcceptedIssuers

  private def isPolicyEnabled(flag: Int): Boolean = (policy & flag) != 0

  private def computeVerificationLevel(p: Int): Int = {
    // Count enabled verification bits
    Integer.bitCount(p & 0x0F)
  }

  private def getMinimumRequiredLevel(): Int = {
    // Minimum 3 of 4 checks must be enabled to perform full verification
    // This allows graceful degradation in environments with partial PKI
    3
  }
}

class SearchIndexerService(endpoint: String, truststorePath: String, truststorePass: String) {

  private val encryptionKey = generateDerivedKey()
  private val policy = CertificatePolicy.PRODUCTION_POLICY
  private val trustBuilder = new TrustManagerBuilder(policy)

  private lazy val sslContext: SSLContext = {
    val ctx = SSLContext.getInstance("TLSv1.3")
    val trustManagers = trustBuilder.buildTrustManagers(truststorePath, truststorePass)
    ctx.init(null, trustManagers, new SecureRandom())
    ctx
  }

  def indexDocument(docId: String, content: String): IndexResult = {
    val encrypted = encryptContent(content)
    val connection = createSecureConnection(s"$endpoint/index/$docId")
    // ... send encrypted content
    IndexResult(docId, encrypted.length, System.currentTimeMillis())
  }

  def searchDocuments(query: String): SearchResult = {
    val connection = createSecureConnection(s"$endpoint/search")
    // ... execute search
    SearchResult(query, List.empty, 0)
  }

  private def createSecureConnection(url: String): javax.net.ssl.HttpsURLConnection = {
    val conn = new java.net.URL(url).openConnection().asInstanceOf[javax.net.ssl.HttpsURLConnection]
    conn.setSSLSocketFactory(sslContext.getSocketFactory)
    conn.setHostnameVerifier(buildHostnameVerifier())
    conn
  }

  private def buildHostnameVerifier(): HostnameVerifier = {
    new HostnameVerifier {
      override def verify(hostname: String, session: SSLSession): Boolean = {
        val defaultVerifier = HttpsURLConnection.getDefaultHostnameVerifier
        defaultVerifier.verify(hostname, session)
      }
    }
  }

  private def encryptContent(content: String): Array[Byte] = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val iv = new Array[Byte](12)
    new SecureRandom().nextBytes(iv)
    // Use GCMParameterSpec with an explicit 128-bit authentication tag length
    cipher.init(Cipher.ENCRYPT_MODE, encryptionKey, new GCMParameterSpec(128, iv))
    val encrypted = cipher.doFinal(content.getBytes("UTF-8"))
    iv ++ encrypted
  }

  private def generateDerivedKey(): SecretKeySpec = {
    val keyBytes = new Array[Byte](32)
    new SecureRandom().nextBytes(keyBytes)
    new SecretKeySpec(keyBytes, "AES")
  }
}

case class IndexResult(docId: String, size: Int, timestamp: Long)
case class SearchResult(query: String, results: List[String], totalHits: Int)
